using EddaStore.Models.Coupons; using EddaStore.Repositories.Interfaces; using EddaStore.Services.Interfaces;
namespace EddaStore.Services;
public class CouponService(IGenericRepository<Coupon> repository):ICouponService { public Task<IReadOnlyList<Coupon>> GetAllAsync(CancellationToken ct=default)=>repository.GetAllAsync(ct); public Task<Coupon?> GetAsync(Guid id,CancellationToken ct=default)=>repository.GetByIdAsync(id,ct); public async Task CreateAsync(Coupon x,CancellationToken ct=default){await Validate(x,null,ct);await repository.AddAsync(x,ct);await repository.SaveChangesAsync(ct);} public async Task UpdateAsync(Coupon x,CancellationToken ct=default){var e=await repository.GetByIdAsync(x.Id,ct)??throw new KeyNotFoundException();await Validate(x,x.Id,ct);e.Code=x.Code;e.Description=x.Description;e.DiscountType=x.DiscountType;e.DiscountValue=x.DiscountValue;e.MinimumOrderAmount=x.MinimumOrderAmount;e.MaximumDiscountAmount=x.MaximumDiscountAmount;e.UsageLimit=x.UsageLimit;e.StartsAt=x.StartsAt;e.ExpiresAt=x.ExpiresAt;e.IsActive=x.IsActive;repository.Update(e);await repository.SaveChangesAsync(ct);}public async Task DeleteAsync(Guid id,CancellationToken ct=default){var e=await repository.GetByIdAsync(id,ct)??throw new KeyNotFoundException();repository.Delete(e);await repository.SaveChangesAsync(ct);}private async Task Validate(Coupon x,Guid? id,CancellationToken ct){x.Code=x.Code.Trim().ToUpperInvariant();if(x.ExpiresAt<=x.StartsAt)throw new ArgumentException("تاريخ الانتهاء يجب أن يأتي بعد تاريخ البدء.");if(x.DiscountType is not ("Percentage" or "FixedAmount"))throw new ArgumentException("نوع الخصم غير صالح.");if(x.DiscountType=="Percentage"&&x.DiscountValue>100)throw new ArgumentException("الخصم النسبي لا يتجاوز 100%.");if(x.MaximumDiscountAmount.HasValue&&x.DiscountType!="Percentage")throw new ArgumentException("أقصى خصم متاح للخصم النسبي فقط.");if((await repository.GetAllAsync(ct)).Any(c=>c.Code==x.Code&&c.Id!=id))throw new ArgumentException("كود الخصم مستخدم بالفعل.");}}
